import{_ as a,o,c as r,a2 as s}from"./chunks/framework.DHmNT4rz.js";const u=JSON.parse('{"title":"Redis, queues, and caching","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"develop/skills/redis-cache-jobs.md","filePath":"develop/skills/redis-cache-jobs.md","lastUpdated":null}'),t={name:"develop/skills/redis-cache-jobs.md"};function i(c,e,n,d,l,p){return o(),r("div",null,[...e[0]||(e[0]=[s('<div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This page mirrors <a href="https://github.com/mathias7799/SaaSWeave/blob/main/.agents/skills/redis-workers-cache/references/redis-cache-jobs.md" target="_blank" rel="noreferrer"><code>.agents/skills/redis-workers-cache/references/redis-cache-jobs.md</code></a> from the repository. Edit it at the source, not here.</p></div><h1 id="redis-queues-and-caching" tabindex="-1">Redis, queues, and caching <a class="header-anchor" href="#redis-queues-and-caching" aria-label="Permalink to &quot;Redis, queues, and caching&quot;">​</a></h1><p>Reference for Redis-backed caching, BullMQ queues, and worker processors in SaaSWeave. The <a href="https://github.com/mathias7799/SaaSWeave/blob/main/.agents/skills/redis-workers-cache/SKILL.md" target="_blank" rel="noreferrer">redis-workers-cache skill</a> covers when to apply this and how to validate a change; this file holds the durable patterns.</p><p>Redis is optional infrastructure for cache reads and required infrastructure for queues and workers. Keep cache, queue, and worker code in the shared packages so features can opt in without coupling to one page or router.</p><h2 id="package-boundaries" tabindex="-1">Package boundaries <a class="header-anchor" href="#package-boundaries" aria-label="Permalink to &quot;Package boundaries&quot;">​</a></h2><ul><li>Use <code>@saasweave/cache</code> for Redis connections, cache keys, TTL cache reads, tag invalidation, and Redis readiness.</li><li>Use <code>@saasweave/jobs/queues</code> from API/server code that produces jobs.</li><li>Use <code>@saasweave/jobs/worker</code> only from <code>apps/worker</code>; do not import worker processors into API routers.</li><li>Put reusable DB/storage/provider workflows in <code>@saasweave/app</code>; this package must not import BullMQ dispatch or oRPC routers.</li><li>Keep queue processors and schedule handlers in <code>packages/jobs/src/{worker,domain-workers,schedule-worker}.ts</code>. <code>apps/worker</code> only owns process lifecycle, readiness/metrics HTTP, signals, schedule registration, and composition.</li><li>Keep feature processors idempotent. A retry must not double-charge, double-send a live provider request, or duplicate persisted side effects unless the operation is explicitly idempotent.</li></ul><h2 id="cache-pattern" tabindex="-1">Cache pattern <a class="header-anchor" href="#cache-pattern" aria-label="Permalink to &quot;Cache pattern&quot;">​</a></h2><p>Use <code>cacheWrap(key, loader, { namespace, ttlSeconds, tags })</code> around real database or provider reads that are safe to reuse briefly. Prefer short TTLs for dashboard stats and explicit tag invalidation after writes.</p><p>Use stable keys made from tenant/workspace ids and filters, for example <code>overview:${organizationId}:${range}</code>. Never cache data whose authorization scope is unclear.</p><p>When Redis is unavailable, <code>@saasweave/cache</code> falls back to process memory for cache reads. Readiness still reports Redis unhealthy when <code>REDIS_URL</code> is configured and unreachable.</p><p><strong>Do not cache:</strong> auth sessions, API key verification, export blobs, or raw audit pages.</p><h2 id="queue-pattern" tabindex="-1">Queue pattern <a class="header-anchor" href="#queue-pattern" aria-label="Permalink to &quot;Queue pattern&quot;">​</a></h2><p>Create enqueue helpers in <code>packages/jobs/src/queues.ts</code>. Keep job payloads JSON-serializable and version-tolerant. Store ids, not large objects.</p><p>Create core email/notification processors in <code>packages/jobs/src/worker.ts</code>, domain processors in <code>domain-workers.ts</code>, and cron handlers in <code>schedule-worker.ts</code>; compose them through <code>createAllWorkers()</code>. The worker app owns lifecycle, signal handling, health/metrics HTTP, and connection cleanup.</p><p>Use stable, unique <code>jobId</code> values for deduplication. Keep payloads small and reload authoritative state inside the processor. For long exports, keep streaming and byte/row limits in <code>packages/app</code>; progress counters do not imply resumability unless the artifact writer also resumes safely.</p><h2 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to &quot;Retention&quot;">​</a></h2><p>Retention is a scheduled job, not ad hoc request cleanup. Add product-data deletion queries in <code>packages/db</code>, storage deletion in <code>packages/app</code>, and orchestration/metrics in <code>packages/jobs/src/retention/</code>. Respect legal holds and dry-run configuration.</p><h2 id="environment-surfaces" tabindex="-1">Environment surfaces <a class="header-anchor" href="#environment-surfaces" aria-label="Permalink to &quot;Environment surfaces&quot;">​</a></h2><p>When adding Redis/worker settings, update all env surfaces:</p><ul><li><code>packages/env/src/server/env.ts</code></li><li><code>.env.docker.example</code></li><li><code>packages/env/.env.example</code></li><li><code>docker-compose.yaml</code></li><li><code>docker-compose.coolify.yaml</code></li><li><code>packages/env/README.md</code> or the relevant operations runbook</li></ul><p>Use <code>REDIS_URL</code>, <code>CACHE_PREFIX</code>, <code>CACHE_DEFAULT_TTL_SECONDS</code>, <code>QUEUE_PREFIX</code>, and <code>WORKER_CONCURRENCY</code> before adding new knobs.</p><h2 id="runtime-hardening" tabindex="-1">Runtime hardening <a class="header-anchor" href="#runtime-hardening" aria-label="Permalink to &quot;Runtime hardening&quot;">​</a></h2><p>Production Compose keeps server/web/worker containers read-only with dropped capabilities, resource limits, and health checks. Keep worker port 9100 private; its metrics endpoint has no application authentication. Server metrics require <code>METRICS_BEARER_TOKEN</code> when enabled.</p>',23)])])}const m=a(t,[["render",i]]);export{u as __pageData,m as default};
